18	)
19	
20	// DEVDESK-330 step 7: the container, network and trace rows at 80 and 60
21	// columns, with names that do not fit, wide characters and IPv6.
22	
23	const (
24		// addressCellsAt80 is the Address column at 80 columns (plan H5): 78 minus
25		// four paddings of two, minus Hop 3, Step 11 and RTT 9.
26		addressCellsAt80 = 47
27	
28		longCtrName = "payments-gateway-worker-eu-west-1-blue-green-0123456789" // 55 cells
29		longNetName = "customer-facing-backend-overlay-network-01"              // 41 cells
30		cjkCtrName  = "日本語のコンテナ名前日本語のコンテナ名前日本語"                                 // 24 wide runes, 48 cells
31	)
32	
33	// layoutCase is one container as the engine described it.
34	type layoutCase struct {
35		name string
36		ctr  docker.ContainerNetworking
37	}
38	
39	func layoutCases() []layoutCase {
40		v4 := func(name, net string) docker.ContainerNetworking {
41			return docker.ContainerNetworking{
42				Name: name, Running: true, Mode: net,
43				Networks: []docker.EndpointNetwork{{
44					Name: net, IPv4: netip.MustParseAddr("172.18.0.5"), Gateway: netip.MustParseAddr("172.18.0.1"),
45				}},
46			}
47		}
48		v6 := v4(longCtrName, longNetName)
49		v6.Networks[0].IPv4 = netip.MustParseAddr("2001:db8:85a3:0:0:8a2e:370:7334")
