72	
73		route := netcheck.RouteHop{Interface: longIface, Source: net.ParseIP("192.168.1.21"), Gateway: net.ParseIP("192.168.1.1")}
74		m = feed(t, m, pathResolvedMsg{gen: gen, addr: netip.MustParseAddr("198.51.100.30"), route: route, source: src, ctr: lc.ctr})
75		var hops []nettrace.Hop
76		for ttl := 1; ttl <= manyHops; ttl++ {
77			h := nettrace.Hop{TTL: ttl, Kind: nettrace.HopRouter, Addr: netip.MustParseAddr("2001:db8:85a3:0:0:8a2e:370:7334")}
78			if ttl == manyHops {
79				h = nettrace.Hop{TTL: ttl, Kind: nettrace.HopTarget, Addr: netip.MustParseAddr("198.51.100.30")}
80			}
81			hops = append(hops, h)
82			m = feed(t, m, pathHopMsg{gen: gen, hop: h})
83		}
84		switch state {
